      "在应用边界定义一组可用操作，协调领域对象、事务和外部端口对每个用例的响应。只交付合同、输入和基线，让复核者先预测再运行；接受、拒绝、首差和回退必须一致，沿“请求 → 业务规则 → 领域组织 → 事务 → 结果”逐节点检查规则复杂度、对象协作、表结构、服务边界、演化成本。先写预期，再执行正常、恰好边界和单故障样本，保存查询、远程、事务、会话、首差和回退证据。通过标准是“能让服务层只负责编排与事务，不复制领域规则，并给出客户端可依赖的稳定操作契约。”；最后由独立复核者在相同边界重建结果，并说明至少一个被拒绝的替代方案。",
    tags: ["规则复杂度", "2024中文版", "可重放", "level-3"],
